      '<div><dt>Related exercise</dt><dd>' + (f.explore ? 'In-browser exploration below' : 'None for this lesson') + (f.mods.length ? '; Microsoft Foundry labs: ' + f.mods.map(function (m) { return '<a href="#/lab/' + m + '">' + m + '</a>'; }).join(', ') : '') + '</dd></div>' +
      '</dl>';
